/bin/bash -lc "node <<'JS'
const fs = require('node:fs');
const vm = require('node:vm');
const { spawnSync } = require('node:child_process');
const html = fs.readFileSync('/workspace/index.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
const syntax = spawnSync(process.execPath, ['--check'], { input: script, encoding: 'utf8' });
if (syntax.status) throw Error(syntax.stderr);
console.log('JavaScript syntax: passed');
function exercise(reducedMotion, width, height) {
  const callbacks = new Map();
  let nextId = 0, paintCount = 0;
  const noop = () => {};
  const context = new Proxy({}, { get: (target, key) => target[key] ?? (key.startsWith('create') ? () => ({ addColorStop: noop }) : key === 'fillRect' ? () => paintCount++ : noop), set: (target, key, value) => (target[key] = value, true) });
  function element() { return { listeners: {}, attributes: {}, addEventListener(type, cb) { this.listeners[type] = cb; }, setAttribute(key, value) { this.attributes[key] = value; } }; }
  const ids = ['pond', 'rain', 'pause', 'status', 'pause-label', 'pause-icon'];
  const elements = Object.fromEntries(ids.map(id => ['#' + id, element()]));
  elements['#pond'].getContext = () => context;
  elements['#pond'].getBoundingClientRect = () => ({ width, height, left: 0, top: 0 });
  const document = { ...element(), hidden: false, querySelector: key => elements[key] };
  const window = element();
  vm.runInNewContext(script, { document, window, matchMedia: () => ({ ...element(), matches: reducedMotion }), devicePixelRatio: 2, requestAnimationFrame(cb) { callbacks.set(++nextId, cb); return nextId; }, cancelAnimationFrame(id) { callbacks.delete(id); } });
  const step = time => { const scheduled = [...callbacks.values()]; callbacks.clear(); scheduled.forEach(cb => cb(time)); if (callbacks.size > 1) throw Error('Duplicate animation loop'); };
  if (reducedMotion && callbacks.size) throw Error('Reduced motion was ignored');
  elements['#pond'].listeners.pointerdown({ button: 0, clientX: width / 2, clientY: height / 2 });
  elements['#pond'].listeners.keydown({ code: 'Space', preventDefault: noop, repeat: false });
  elements['#rain'].listeners.click();
  if (elements['#rain'].attributes['aria-pressed'] "'!== '"'true') throw Error('Rain toggle failed');
  if (reducedMotion) elements['#pause'].listeners.click();
  for (let i = 0; i < 600; i++) step(i * 16.667);
  elements['#pause'].listeners.click();
  if (callbacks.size) throw Error('Pause failed');
  elements['#pause'].listeners.click();
  document.hidden = true;
  document.listeners.visibilitychange();
  if (callbacks.size) throw Error('Hidden tab continued animating');
  document.hidden = false;
  document.listeners.visibilitychange();
  window.listeners.resize();
  step(11000);
  if ("'!callbacks.size || paintCount < 600) throw Error('"'Resume failed');
  console.log("'`${width}×${height}, reduced motion ${reducedMotion}: drawing, input, rain, pause, resize, and tab lifecycle passed`);
}
exercise(false, 1440, 900);
exercise(true, 390, 700);
JS'

